// Нормализация входа из Telegram Trigger
const msg = $input.first().json;

const chatId = msg.message?.chat?.id || 'unknown';
const text = msg.message?.text || '';

return [{
  json: {
    chatInput: text,
    sessionId: `tg_${chatId}`,
    source: 'telegram',
    chatId: String(chatId)
  }
}];

// Route output: если source === telegram, формируем ответ для Telegram
const items = $input.all();
const results = [];

for (const item of items) {
  const source = item.json.source || 'chat_ui';
  const output = item.json.output || item.json.text || 'Нет ответа';
  const chatId = item.json.chatId || '1607573116';

  if (source === 'telegram') {
    // Ограничение Telegram: макс 4096 символов
    let text = output;
    if (text.length > 4000) {
      text = text.substring(0, 3997) + '...';
    }
    results.push({
      json: {
        source: 'telegram',
        chatId,
        text
      }
    });
  } else {
    // Chat UI — ответ возвращается автоматически
    results.push({
      json: {
        source: 'chat_ui',
        text: output
      }
    });
  }
}

return results;
